create table if not exists public.coupon_redemptions (id bigint generated always as identity primary key,coupon_id bigint not null references public.coupons(id) on delete restrict,user_id uuid not null references auth.users(id) on delete cascade,order_id bigint not null references public.orders(id) on delete cascade,amount numeric not null check(amount >= 0),created_at timestamptz not null default now(),unique(coupon_id,order_id));
create unique index if not exists gift_card_redemptions_code_order_uidx on public.gift_card_redemptions(gift_card_code_id,order_id) where order_id is not null;
create or replace function public.finalize_order_promotions(p_order_id bigint,p_user_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare o public.orders%rowtype;c public.coupons%rowtype;g public.gift_card_codes%rowtype;used_count bigint; begin select * into o from public.orders where id=p_order_id and user_id=p_user_id for update;if not found then raise exception 'Order not found';end if;if o.coupon_code is not null and coalesce(o.coupon_discount,0)>0 then select * into c from public.coupons where code=o.coupon_code for update;if not found or not c.is_active then raise exception 'Coupon is no longer valid';end if;if c.expires_at is not null and c.expires_at<=now() then raise exception 'Coupon has expired';end if;if c.usage_limit is not null then select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id;if used_count>=c.usage_limit and not exists(select 1 from public.coupon_redemptions where coupon_id=c.id and order_id=o.id) then raise exception 'Coupon usage limit reached';end if;end if;insert into public.coupon_redemptions(coupon_id,user_id,order_id,amount) values(c.id,p_user_id,o.id,o.coupon_discount) on conflict(coupon_id,order_id) do nothing;end if;if o.gift_card_code is not null and coalesce(o.gift_card_discount,0)>0 then select * into g from public.gift_card_codes where code=o.gift_card_code for update;if not found or not g.is_active then raise exception 'Gift card is no longer valid';end if;if g.expires_at is not null and g.expires_at<=now() then raise exception 'Gift card has expired';end if;if not exists(select 1 from public.gift_card_redemptions where gift_card_code_id=g.id and order_id=o.id) then if g.balance<o.gift_card_discount then raise exception 'Gift card balance changed; contact support';end if;update public.gift_card_codes set balance=balance-o.gift_card_discount,updated_at=now() where id=g.id;insert into public.gift_card_redemptions(gift_card_code_id,user_id,order_id,amount) values(g.id,p_user_id,o.id,o.gift_card_discount);end if;end if;end $$;revoke all on function public.finalize_order_promotions(bigint,uuid) from public,anon,authenticated;